import { inject } from '@angular/core';
import { HttpInterceptorFn } from '@angular/common/http';

export const authInterceptor: HttpInterceptorFn = (req, next) => {
  const token = inject(AuthService).token();   // angenommen: Token als Signal

  // Nur eigene API-Aufrufe erhalten das Token
  if (!token || !req.url.startsWith('api/')) {
    return next(req);
  }

  // req ist unveränderlich: veränderte Kopie erzeugen
  const authReq = req.clone({
    setHeaders: { Authorization: `Bearer ${token}` }
  });
  return next(authReq);
};

export class CustomerDetailsComponent {
  id = input<string>();

  customer = resource({
    // 1. Parameter: reaktiv, undefined = nichts laden
    params: () => this.id() ? { id: this.id()! } : undefined,

    // 2. Loader: Angular ruft ihn bei jeder Parameter-Änderung auf
    loader: async ({ params, abortSignal }) => {
      const res = await fetch(`api/customer/${params.id}`, { signal: abortSignal });
      if (!res.ok) {
        throw new Error(`HTTP ${res.status}`);   // → Zustand error
      }
      return (await res.json()) as Customer;     // → Zustand resolved
    }
  });
}

