// afterNextRender, PLATFORM_ID: @angular/core
// isPlatformBrowser: @angular/common
export class CustomerListComponent {
  private readonly platformId = inject(PLATFORM_ID);
  filterText = signal('');

  constructor() {
    // nur im Browser, einmal nach dem ersten Rendern
    afterNextRender(() => {
      this.filterText.set(localStorage.getItem('filter') ?? '');
    });
  }
  saveFilter(): void {
    if (isPlatformBrowser(this.platformId)) {
      localStorage.setItem('filter', this.filterText());
    }
  }
}

